package com.mockarena.assessment.application;
import com.mockarena.assessment.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service public class AttemptSubmissionApplicationService {
 private final AttemptRepository attempts; private final AttemptSubmitRequestRepository requests; private final Clock clock=Clock.systemUTC();
 public AttemptSubmissionApplicationService(AttemptRepository attempts,AttemptSubmitRequestRepository requests){this.attempts=attempts;this.requests=requests;}
 @Transactional public Submission submit(UUID attemptId,UUID candidate,String key){if(key==null||key.isBlank()||key.length()>200)throw new IllegalArgumentException("Idempotency-Key is required"); Attempt attempt=attempts.findByIdForUpdate(attemptId).orElseThrow(AttemptNotFoundException::new);if(!attempt.candidateUserId().equals(candidate))throw new SecurityException("Attempt is not owned by current user"); AttemptSubmitRequest replay=requests.findByAttemptIdAndIdempotencyKey(attemptId,key.trim()).orElse(null);if(replay!=null){if(!replay.candidateUserId().equals(candidate))throw new IdempotencyKeyReusedException();return new Submission(attempt.id(),attempt.status().name(),replay.submittedAt(),attempt.deadlineAt());} Instant now=clock.instant();if(attempt.expireIfDue(now)){attempts.saveAndFlush(attempt);throw new IllegalStateException("Attempt is not in progress");} attempt.submit(now);attempts.saveAndFlush(attempt);requests.saveAndFlush(new AttemptSubmitRequest(UUID.randomUUID(),attemptId,candidate,key.trim(),now));return new Submission(attempt.id(),attempt.status().name(),attempt.submittedAt(),attempt.deadlineAt()); }
 public record Submission(UUID attemptId,String status,Instant submittedAt,Instant deadlineAt){}
}
